action.command:
node -e "
const { execSync } = require('child_process');
const fs = require('fs');
const path = require('path');

// Get all staged + modified files tracked by git
let files = [];
try {
  const staged = execSync('git diff --cached --name-only', { encoding: 'utf-8' }).trim();
  const modified = execSync('git diff --name-only', { encoding: 'utf-8' }).trim();
  const allFiles = [...new Set([...staged.split('\n'), ...modified.split('\n')])];
  files = allFiles.filter(f => f.length > 0 && fs.existsSync(f));
} catch (e) {
  console.log('security-precommit-scanner: could not list git files, scanning all src files');
  const srcFiles = execSync('git ls-files', { encoding: 'utf-8' }).trim().split('\n');
  files = srcFiles.filter(f => f.endsWith('.ts') || f.endsWith('.json') || f.endsWith('.env') || f.endsWith('.yml'));
}

// Secret patterns — covers AWS, OpenAI, ElevenLabs, GitHub, generic tokens
const patterns = [
  { name: 'AWS Access Key',       re: /AKIA[0-9A-Z]{16}/ },
  { name: 'AWS Secret Key',       re: /aws_secret_access_key\s*=\s*[A-Za-z0-9/+]{40}/ },
  { name: 'AWS Session Token',    re: /aws_session_token\s*=\s*[A-Za-z0-9/+=]{100,}/ },
  { name: 'OpenAI API Key',       re: /sk-[A-Za-z0-9]{32,}/ },
  { name: 'ElevenLabs API Key',   re: /xi_api_key[^\n]{0,20}[A-Za-z0-9]{32}/ },
  { name: 'GitHub Token',         re: /ghp_[A-Za-z0-9]{36}/ },
  { name: 'GitHub OAuth',         re: /gho_[A-Za-z0-9]{36}/ },
  { name: 'Bedrock Credentials',  re: /bedrock[_-]?api[_-]?key[^\n]{0,20}[A-Za-z0-9]{20}/ },
  { name: 'Generic Secret',       re: /['\"]?(?:secret|password|passwd|api_key|apikey|token|auth_token)['\"]?\s*[:=]\s*['\"][A-Za-z0-9!@#$%^&*]{12,}['\"]/ },
  { name: 'Private Key Header',   re: /-----BEGIN (?:RSA |EC )?PRIVATE KEY-----/ },
  { name: 'Bearer Token',         re: /Authorization:\s*Bearer [A-Za-z0-9._\-]{20,}/ },
];

const findings = [];

for (const file of files) {
  let content;
  try { content = fs.readFileSync(file, 'utf-8'); } catch { continue; }

  for (const pattern of patterns) {
    if (pattern.re.test(content)) {
      const lines = content.split('\n');
      lines.forEach((line, i) => {
        if (pattern.re.test(line)) {
          findings.push({ file, line: i + 1, pattern: pattern.name, snippet: line.trim().slice(0, 80) });
        }
      });
    }
  }
}

if (findings.length > 0) {
  console.error('\n🚨 SECURITY SCAN FAILED — Potential secrets detected:\n');
  findings.forEach(f => {
    console.error('  FILE: ' + f.file + ':' + f.line);
    console.error('  PATTERN: ' + f.pattern);
    console.error('  SNIPPET: ' + f.snippet.replace(/./g, '*') + '  [REDACTED]');
    console.error('');
  });
  console.error('ACTION REQUIRED: Remove credentials before committing.');
  console.error('  - Use environment variables or .env files (already in .gitignore)');
  console.error('  - Run: git reset HEAD <file> to unstage');
  process.exit(1);
} else {
  console.log('✅ security-precommit-scanner: no secrets detected in ' + files.length + ' files.');
}
"
